/*
 * prog55_connected_components.c
 *
 * Re‑implementation of the original program whose behaviour is observed
 * from the disassembly.  The program reads an undirected graph with up
 * to 8 vertices (numbered 0‑7) from the command line, one edge per pair
 * of arguments, builds an adjacency matrix and prints the connected
 * components.
 *
 * Output format (exactly as the original binary):
 *
 *   0: {0,1,2}
 *   1: {3,4}
 *   …
 *
 * If any vertex index is outside the range [0,7] the program prints
 *   INVALID_INPUT
 * and exits with status 1.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8                     /* maximum number of vertices */

int main(int argc, char **argv)
{
    /* -----------------------------------------------------------------
     *  1.  Parse the command line.
     * ----------------------------------------------------------------- */
    if (argc < 3 || ((argc - 1) & 1)) {          /* need an even number of ints */
        puts("INVALID_INPUT");
        return 1;
    }

    int adj[MAXV][MAXV] = {{0}};                 /* adjacency matrix */

    for (int i = 1; i < argc; i += 2) {
        long u = strtol(argv[i],     NULL, 10);
        long v = strtol(argv[i + 1], NULL, 10);

        if (u < 0 || u >= MAXV || v < 0 || v >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }

        adj[(int)u][(int)v] = 1;
        adj[(int)v][(int)u] = 1;                 /* undirected */
    }

    /* -----------------------------------------------------------------
     *  2.  Find connected components with a simple BFS.
     * ----------------------------------------------------------------- */
    int visited[MAXV] = {0};
    int queue[MAXV];                             /* circular queue – size is enough */
    int comp = 0;                                /* component counter */

    for (int start = 0; start < MAXV; ++start) {
        if (visited[start])
            continue;                           /* already part of a previous component */

        /* start a new component */
        int qhead = 0, qtail = 0;
        queue[qtail++] = start;
        visited[start] = 1;

        printf("%d:", comp);
        printf(" {");

        int first = 1;                           /* first vertex printed in this component */

        while (qhead < qtail) {
            int u = queue[qhead++];

            if (!first)
                putchar(',');                   /* separator between vertices */
            printf("%d", u);
            first = 0;

            /* enqueue all unvisited neighbours of u */
            for (int v = 0; v < MAXV; ++v) {
                if (adj[u][v] && !visited[v]) {
                    visited[v] = 1;
                    queue[qtail++] = v;
                }
            }
        }

        putchar('}');
        putchar('\n');
        ++comp;
    }

    return 0;
}
